  /**
   * @method
   * @name deepcoin#fetchOpenOrder
   * @description fetch an open order by it's id
   * @see https://www.deepcoin.com/docs/DeepCoinTrade/orderByID
   * @param {string} id order id
   * @param {string} symbol unified market symbol, default is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  fetchOpenOrder(std::any id, std::any symbol = std::any{},
                 std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchClosedOrder() requires a symbol argument"))));
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("instId"),
                      ::getValue(market, std::string("id"))},
                     {std::string("ordId"), id},
                 };
                 std::any response =
                     awaitValue(this->privateGetDeepcoinTradeOrderByID(
                         this->extend(request, params)));
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 std::any length = getArrayLength(data);
                 if (isTrue(isEqual(length, 0))) {
                   throw OrderNotFound(toString(add(
                       add(this->id,
                           std::string(
                               " fetchOpenOrder() could not find order id ")),
                       id)));
                 }
                 std::any entry = this->safeDict(data, 0, ccxt::dict{});
                 return this->parseOrder(entry, market);
               })
        .share();
  }

  /**
   * @method
   * @name deepcoin#fetchCanceledAndClosedOrders
   * @see https://www.deepcoin.com/docs/DeepCoinTrade/ordersHistory
   * @see https://www.deepcoin.com/docs/DeepCoinTrade/triggerOrdersHistory
   * @description fetches information on multiple canceled and closed orders
   * made by the user
   * @param {string} [symbol] unified market symbol of the market orders were
   * made in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {bool} [params.trigger] whether to fetch trigger/algo orders
   * (default false)
   * @param {string} [params.type] *non trigger orders only* 'spot' or 'swap',
   * the market type for the orders
   * @param {string} [params.state] *non trigger orders only* 'canceled' or
   * 'filled', the order state to filter by
   * @param {string} [params.OrderType] *trigger orders only* 'limit' or
   * 'market'
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any> fetchCanceledAndClosedOrders(
      std::any symbol = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any paginate = false;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchCanceledAndClosedOrders"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchCanceledAndClosedOrders"), symbol,
                       since, limit, params));
                 }
                 std::any trigger =
                     this->safeBool(params, std::string("trigger"), false);
                 std::any methodName =
                     std::string("fetchCanceledAndClosedOrders");
                 std::any methodNameparamsVariable = this->handleParamString(
                     params, std::string("methodName"), methodName);
                 methodName = ::getValue(methodNameparamsVariable, 0);
                 params = ::getValue(methodNameparamsVariable, 1);
                 std::any market = std::any{};
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("instId"),
                              ::getValue(market, std::string("id")));
                 }
                 std::any marketType = std::string("spot");
                 std::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(methodName, market, params,
                                                     marketType);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 ::setValue(request, std::string("instType"),
                            this->convertToInstrumentType(marketType));
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"),
                              limit); // default 100
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(trigger, true))) {
                   if (isTrue(!isEqual(
                           methodName,
                           std::string("fetchCanceledAndClosedOrders")))) {
                     throw BadRequest(toString(add(
                         add(add(this->id, std::string(" ")), methodName),
                         std::string("() does not support trigger orders"))));
                   }
                   if (isTrue(isEqual(market, std::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id,
                         std::string(" fetchCanceledAndClosedOrders() requires "
                                     "a symbol argument for trigger orders"))));
                   }
                   params = this->omit(params, std::string("trigger"));
                   //
                   //     {
                   //         "code": "0",
                   //         "msg": "",
                   //         "data": [
                   //             {
                   //                 "instType": "SWAP",
                   //                 "instId": "DOGE-USDT-SWAP",
                   //                 "ordId": "1001110510915416",
                   //                 "px": "0",
                   //                 "sz": "76",
                   //                 "triggerPx": "0",
                   //                 "triggerPxType": "last",
                   //                 "ordType": "TPSL",
                   //                 "side": "sell",
                   //                 "posSide": "long",
                   //                 "tdMode": "cross",
                   //                 "lever": "2",
                   //                 "triggerTime": "0",
                   //                 "uTime": "1761059366000",
                   //                 "cTime": "1761059218",
                   //                 "errorCode": "0",
                   //                 "errorMsg": ""
                   //             }
                   //         ]
                   //     }
                   //
                   response = awaitValue(
                       this->privateGetDeepcoinTradeTriggerOrdersHistory(
                           this->extend(request, params)));
                 } else {
                   //
                   //     {
                   //         "code": "0",
                   //         "msg": "",
                   //         "data": [
                   //             {
                   //                 "instType": "SPOT",
                   //                 "instId": "ETH-USDT",
                   //                 "tgtCcy": "",
                   //                 "ccy": "",
                   //                 "ordId": "1001434573319675",
                   //                 "clOrdId": "",
                   //                 "tag": "",
                   //                 "px": "4056.620000000000",
                   //                 "sz": "0.004000",
                   //                 "pnl": "0.000000",
                   //                 "ordType": "market",
                   //                 "side": "buy",
                   //                 "posSide": "",
                   //                 "tdMode": "cash",
                   //                 "accFillSz": "0.004000",
                   //                 "fillPx": "",
                   //                 "tradeId": "",
                   //                 "fillSz": "0.004000",
                   //                 "fillTime": "1760619119000",
                   //                 "avgPx": "",
                   //                 "state": "filled",
                   //                 "lever": "1.000000",
                   //                 "tpTriggerPx": "",
                   //                 "tpTriggerPxType": "",
                   //                 "tpOrdPx": "",
                   //                 "slTriggerPx": "",
                   //                 "slTriggerPxType": "",
                   //                 "slOrdPx": "",
                   //                 "feeCcy": "USDT",
                   //                 "fee": "0.000004",
                   //                 "rebateCcy": "",
                   //                 "source": "",
                   //                 "rebate": "",
                   //                 "category": "normal",
                   //                 "uTime": "1760619119000",
                   //                 "cTime": "1760619119000"
                   //             }
                   //         ]
                   //     }
                   //
                   response =
                       awaitValue(this->privateGetDeepcoinTradeOrdersHistory(
                           this->extend(request, params)));
                 }
                 // todo handle with since, until and pagination
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseOrders(data, market, since, limit);
               })
        .share();
  }

